begin;
do $test$ declare owner_id uuid:=gen_random_uuid();user_id uuid:=gen_random_uuid();manager_id uuid:=gen_random_uuid();s uuid;other_store uuid;x jsonb;rid uuid;begin
 insert into auth.users(id,email,email_confirmed_at) values(owner_id,'control-owner@example.invalid',now()),(user_id,'control-observer@example.invalid',now()),(manager_id,'control-merchant@example.invalid',now());
 insert into pitacco_private.platform_owner(user_id,login_name_hash) values(owner_id,sha256(convert_to('control-owner','UTF8'))) on conflict(singleton) do update set user_id=excluded.user_id;
 insert into public.stores(name) values('Control Central') returning id into s;
 insert into public.stores(name) values('Control Other') returning id into other_store;
 insert into public.store_members(store_id,user_id,role) values(s,manager_id,'gestor');
 perform set_config('request.jwt.claim.sub',owner_id::text,true);perform set_config('request.jwt.claims','{"aal":"aal1"}',true);
 assert (public.pitacco_control_access()->>'owner')::boolean;
 x:=public.pitacco_control_dashboard(current_date-1,current_date);assert x->'stores' ? 'mrr' and jsonb_array_length(x->'series')=2;
 assert x#>>'{finance,costs}' is null,'Unknown costs must not become zero';
 insert into public.orders(store_id,channel,gross,status,source,preparation_status,receipt) values(s,'Delivery próprio',123,'accepted','proprio','completed','{}'),(s,'Delivery próprio',777,'cancelled','proprio','completed','{}'),(s,'Delivery próprio',9999,'accepted','proprio','completed','{"is_test":true}');
 x:=public.pitacco_control_dashboard(current_date,current_date);
 assert (x#>>'{orders,gross}')::numeric=123,'Merchant gross excludes cancelled and explicit test orders';
 assert (x#>>'{finance,revenue}')::numeric=0,'Merchant sales never become platform revenue';
 assert x->'cohort' is not null and jsonb_array_length(x->'forecast')=30;

 x:=public.pitacco_control_stores('Control Central');assert (x->>'total')::int=1;
 foreach rid in array array[s,other_store] loop null;end loop;
 begin perform public.pitacco_control_mutate('cost','{"category":"operational","description":"Fixture cost","amount_cents":1250,"incurred_on":"2026-11-26","reference":"test-one"}');raise exception 'TEST MFA bypass';exception when insufficient_privilege then null;end;
 begin perform public.pitacco_owner_set_feature(s,'caixa',false);raise exception 'TEST legacy MFA bypass';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claims','{"aal":"aal2"}',true);
 x:=public.pitacco_control_mutate('cost',jsonb_build_object('category','operational','description','Fixture cost','amount_cents',1250,'incurred_on',current_date,'reference','test-one'));assert (x->>'saved')::boolean;
 x:=public.pitacco_control_dashboard(current_date,current_date);assert (x#>>'{finance,costs}')::numeric=12.5;
 x:=public.pitacco_control_mutate('member',jsonb_build_object('store_id',s,'email','control-observer@example.invalid','role','lojista'));
 assert exists(select 1 from public.store_members m where m.store_id=s and m.user_id=(x->>'id')::uuid and m.role='lojista');
 begin perform public.pitacco_control_mutate('member',jsonb_build_object('store_id',s,'email','control-merchant@example.invalid','role','lojista'));raise exception 'TEST last manager demotion';exception when invalid_parameter_value then null;end;
 perform public.pitacco_control_record_observation('firebase','operational','Fixture measurement','isolated test',30);
 update pitacco_private.control_observations set observed_at=now()-interval '2 minutes',expires_at=now()-interval '1 minute' where service='firebase';
 assert exists(select 1 from jsonb_array_elements(public.pitacco_control_rows('health')->'rows')r where r->>'id'='firebase' and r->>'status'='no_recent_evidence');
 assert public.pitacco_control_database_check()->>'status'='operational';
 x:=public.pitacco_control_set_update_policy('windows','0.12.38','Política isolada para teste de compatibilidade');
 perform public.pitacco_control_device_ping(s,gen_random_uuid(),'windows','0.12.37');
 begin perform pitacco_private.control_require_current_windows();raise exception 'TEST minimum Windows bypass';exception when insufficient_privilege then null;end;
 perform public.pitacco_control_device_ping(s,gen_random_uuid(),'windows','0.12.38');perform pitacco_private.control_require_current_windows();
 x:=public.pitacco_control_set_update_policy('windows',null,'Retirar exigência depois do teste isolado');perform pitacco_private.control_require_current_windows();
 assert not pitacco_private.control_version_below('2.0.16','2.0.15');assert pitacco_private.control_version_below(null,'2.0.16');

 assert public.pitacco_control_plan_features('free','caixa',false)->>'caixa'='false';
 begin perform public.pitacco_control_mutate('features_bulk',jsonb_build_object('feature','invalid','stores',jsonb_build_array(s),'enabled',true));raise exception 'TEST invalid feature';exception when raise_exception then if sqlerrm='TEST invalid feature' then raise;end if;end;

 for x in select public.pitacco_control_rows(v) from unnest(array['users','costs','charges','devices','health','map','notices','assistance','audit','admins','sessions','settings'])v loop assert x ? 'rows';end loop;
 x:=public.pitacco_control_mutate('admin','{"email":"control-observer@example.invalid","role":"observer"}');assert x->>'id'=user_id::text;
 x:=public.pitacco_control_mutate('assistance',jsonb_build_object('store_id',s,'reason','Investigar falha do lojista'));rid:=(x->>'id')::uuid;
 begin perform public.pitacco_control_assisted_snapshot(rid);raise exception 'TEST no consent';exception when insufficient_privilege then null;end;
 begin perform public.pitacco_control_assistance_consent(s,rid,true);raise exception 'TEST admin self consent';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',manager_id::text,true);
 begin perform public.pitacco_control_dashboard();raise exception 'TEST merchant global data';exception when insufficient_privilege then null;end;
 begin perform public.pitacco_control_assistance_consent(other_store,rid,true);raise exception 'TEST cross store consent';exception when insufficient_privilege then null;end;
 x:=public.pitacco_control_assistance_consent(s,rid,true);
 perform set_config('request.jwt.claim.sub',owner_id::text,true);x:=public.pitacco_control_assisted_snapshot(rid);assert x->>'mode'='read_only' and x#>>'{store,id}'=s::text;
 perform set_config('request.jwt.claim.sub',manager_id::text,true);x:=public.pitacco_control_assistance_consent(s,rid,false);
 perform set_config('request.jwt.claim.sub',owner_id::text,true);begin perform public.pitacco_control_assisted_snapshot(rid);raise exception 'TEST revoked consent';exception when insufficient_privilege then null;end;
 x:=public.pitacco_control_mutate('notice',jsonb_build_object('audience','merchants','store_id',s,'kind','notice','title','Aviso real','body','Teste de comunicado segmentado','starts_at',now()-interval '1 minute','ends_at',now()+interval '1 day'));rid:=(x->>'id')::uuid;
 perform set_config('request.jwt.claim.sub',manager_id::text,true);assert jsonb_array_length(public.pitacco_control_notices(s)->'rows')=1;
 perform set_config('request.jwt.claim.sub',user_id::text,true);assert (public.pitacco_control_access()->>'allowed')::boolean;
 x:=public.pitacco_control_dashboard();begin perform public.pitacco_control_rows('costs');raise exception 'TEST RBAC bypass';exception when insufficient_privilege then null;end;
 begin perform public.pitacco_control_mutate('notice',jsonb_build_object('title','Nope'));raise exception 'TEST observer write';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',owner_id::text,true);x:=public.pitacco_control_mutate('revoke_admin',jsonb_build_object('id',user_id));
 perform set_config('request.jwt.claim.sub',user_id::text,true);begin perform public.pitacco_control_dashboard();raise exception 'TEST revoked admin';exception when insufficient_privilege then null;end;
 assert not has_function_privilege('anon','public.pitacco_control_dashboard(date,date)','execute');
 assert not has_function_privilege('authenticated','public.pitacco_control_record_observation(text,text,text,text,integer)','execute');
 assert not has_table_privilege('authenticated','pitacco_private.control_admins','select');
end $test$;
rollback;
